import React from 'react';
import { Users, ShieldCheck, FileCheck } from 'lucide-react';
export default function VendorsPage(){return <div className="space-y-8"><header><h1 className="text-2xl font-bold">Vendor Management</h1><p className="text-sm text-text-secondary">Approved supplier directory with procurement-ready compliance data.</p></header><div className="grid md:grid-cols-3 gap-5">{[['Supplier Directory','School-scoped vendor master',Users],['Compliance','Tax and contact verification',ShieldCheck],['Quote Comparison','Compare submitted supplier quotes',FileCheck]].map(([a,b,I])=><div className="bg-white rounded-card border border-surface-border shadow-card p-6" key={a as string}><I className="w-6 h-6 text-primary"/><p className="font-bold mt-4">{a as string}</p><p className="text-sm text-text-secondary mt-1">{b as string}</p></div>)}</div></div>}
